@using sv_e34ddc3b3c934516887a64ddc0394952.Services
@inject WarehouseState Warehouse
@implements IDisposable
@rendermode InteractiveServer

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto;"
            value="@Warehouse.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            Warehouse.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        Warehouse.OnChange -= StateHasChanged;
    }
}

@using sv_e34ddc3b3c934516887a64ddc0394952.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge bg-danger rounded-pill ms-2"
      style="@(AlertService.CurrentLowStockCount == 0 ? "display:none;" : "")">
    @AlertService.CurrentLowStockCount
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertCountChanged -= _handler;
        }
    }
}

