@using sv_e34ddc3b3c934516887a64ddc0394952.Services
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Currently viewing: <strong>@Warehouse.CurrentWarehouseName</strong></p>

<div class="card mt-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-4 text-danger">@AlertService.CurrentLowStockCount</p>
        <p class="text-muted">Items below minimum stock level. Polling every 10 seconds.</p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        Warehouse.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollNow();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollNow();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollNow()
    {
        var count = await AlertService.GetLowStockCountAsync(Warehouse.CurrentWarehouseId);
        AlertService.UpdateCount(count);
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, poll immediately for the new warehouse
        await PollNow();
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseHandler is not null)
        {
            Warehouse.OnChange -= _warehouseHandler;
        }
        AlertService.OnAlertCountChanged -= OnAlertChanged;

        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
        _timer?.Dispose();
    }
}

